begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
create function pg_temp.check_rows(q text,want text,label text) returns text language plpgsql security invoker as $test$
declare actual text;begin execute q into actual; return extensions.is(actual,want,label);exception when others then return extensions.fail(label||' SQLSTATE='||sqlstate);end;$test$;
insert into auth.users(id) select ('10000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid from generate_series(1,4)i;
insert into public.profiles select id,'Tenant fixture',null from auth.users where id::text like '10000000-0000-4000-8000-%';
insert into public.barbershops(id,name) values ('20000000-0000-4000-8000-000000000001','A'),('20000000-0000-4000-8000-000000000002','B');
insert into public.barbershop_memberships(user_id,barbershop_id,role,status) values
('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','administrator','active'),
('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','barber','active'),
('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','administrator','active'),
('10000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000001','barber','inactive');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","user_metadata":{"role":"administrator"}}',true);
select pg_temp.check_rows('select count(*)::text from public.barbershops','2','shared member reads both shops');
select lives_ok($$update public.barbershops set name='Renamed' where id='20000000-0000-4000-8000-000000000001'$$,'admin renames A');
select lives_ok($$update public.barbershops set name='Forbidden' where id='20000000-0000-4000-8000-000000000002'$$,'barber B update has no effect');
select pg_temp.check_rows('select name from public.barbershops where id=''20000000-0000-4000-8000-000000000002''','B','B unchanged');
select pg_temp.check_rows('select count(*)::text from public.barbershop_memberships','3','own memberships plus contextual admin listing');
select throws_ok($$update public.barbershops set id='20000000-0000-4000-8000-000000000003'$$,'42501',null,'shop ID immutable');
select throws_ok($$update public.barbershop_memberships set role='administrator'$$,'42501',null,'no self escalation');
select throws_ok($$delete from public.barbershop_memberships$$,'42501',null,'no membership delete');
select throws_ok($$insert into public.barbershop_memberships(user_id,barbershop_id,role,status) values (auth.uid(),'20000000-0000-4000-8000-000000000002','administrator','active')$$,'42501',null,'no membership insert');
reset role;
select is((select name from public.barbershops where id='20000000-0000-4000-8000-000000000001'),'Renamed','authorized update persisted');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.check_rows('select count(*)::text from public.barbershops','1','visibility actor 2');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.check_rows('select count(*)::text from public.barbershops','0','visibility actor 3');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select pg_temp.check_rows('select count(*)::text from public.barbershops','0','visibility actor 4');
reset role;
set local role anon;
select throws_ok('select id from public.barbershops','42501',null,'anonymous shop denied');
reset role;

select ok(not c.relforcerowsecurity,'membership owner can avoid policy recursion') from pg_class c where c.oid='public.barbershop_memberships'::regclass;
select ok(p.prosecdef and p.pronargs=1 and p.prorettype='boolean'::regtype and p.proconfig @> array['search_path=""'] and p.proowner=(select relowner from pg_class where oid='public.barbershop_memberships'::regclass),'helper constrained: '||p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('is_active_member','is_active_admin');
select ok(not has_function_privilege('anon','private.is_active_admin(uuid)','EXECUTE'),'anonymous helper denied');
select ok(not has_function_privilege('service_role','private.is_active_admin(uuid)','EXECUTE'),'service does not need helper');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where n.nspname='private' and p.proname in ('is_active_member','is_active_admin') and a.grantee=0),'helpers no PUBLIC execute');

